// orders · кейс ord-03 (.qa/tests/orders/) — נציג מכירות רואה רק הזמנות של לקוחותיו: משה כהן (через «כניסה כעובד», клиентов нет)
// и rep.json «testtest» (за ним закреплён клиент «test», 2026-10-04)
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page.locator('div').filter({ hasText: employee }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

test.describe('orders — נציג מכירות', () => {
  test('נציג ללא לקוחות משויכים: «הכל 0» ומצב ריק, הזמנות של לקוחות אחרים לא מוצגות #6a38cf5f @desktop @prod-safe', async ({ page }) => {
    await impersonate(page, 'משה כהן');
    try {
      await page.goto('/orders');
      await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
      await expect(page.getByRole('button', { name: 'הכל 0' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('אין הזמנות נכנסות')).toBeVisible();
      await expect(page.getByText('הזמנות שלקוחות ישלחו מהקטלוג יופיעו כאן.')).toBeVisible();
      await expect(page.getByRole('button', { name: /^#\d+ / })).toHaveCount(0);
    } finally {
      await page.getByText('חזרה לחשבון הניהול').click();
      await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
    }
  });

  // За rep.json («testtest») закреплён клиент «test» (2026-10-04, .qa/context.md). Только чтение.
  test('נציג רואה הזמנה של לקוח שהוקצה לו, הזמנה של לקוח אחר — «אין הרשאה» #6a38cf5f @desktop @prod-safe', async ({ browser, page }) => {
    // чужой заказ: admin → карточка клиента «פיצוציה בע'ם» (не закреплён за testtest) → первый заказ
    await page.goto('/customers');
    await page.getByRole('main').getByText('0531231234').click();
    await expect(page).toHaveURL(/\/customers\/[0-9a-f-]{36}$/, { timeout: 20_000 });
    await page.getByRole('main').getByText(/^הזמנה #\d+$/).first().click();
    await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 20_000 });
    const foreignOrder = new URL(page.url()).pathname;

    const ctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/rep.json'), baseURL: test.info().project.use.baseURL });
    const rep = await ctx.newPage();
    try {
      await rep.goto('/orders');
      await rep.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
      const rows = rep.getByRole('button', { name: /^#\d+ / });
      await expect(rows.first()).toBeVisible({ timeout: 20_000 });
      await expect(rep.getByRole('button', { name: 'הכל 0' })).toHaveCount(0);
      // в списке — только заказы закреплённого клиента «test»
      for (const name of await rows.evaluateAll((els) => els.map((e) => e.getAttribute('aria-label') || (e as HTMLElement).innerText.replace(/\s+/g, ' '))))
        expect(name).toMatch(/^#\d+ test /);

      await rows.first().click();
      await expect(rep).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 20_000 });
      await expect(rep.getByRole('heading', { name: /^הזמנה #\d+$/ })).toBeVisible({ timeout: 20_000 });
      await expect(rep.getByText('פריטי ההזמנה')).toBeVisible();
      await expect(rep.getByText('לקוח עסקי')).toBeVisible();

      await rep.goto(foreignOrder);
      await expect(rep.getByText('אין הרשאה לצפות בהזמנה זו — היא שייכת ללקוח אחר.')).toBeVisible({ timeout: 20_000 });
      await expect(rep.getByText('פריטי ההזמנה')).toHaveCount(0);
    } finally {
      await ctx.close();
    }
  });
});
